import sys

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    A = list(map(int, input[1:N+1]))

    prefix = [0] * N
    suffix = [0] * N

    prefix[0] = A[0]
    for i in range(1, N):
        prefix[i] = math.gcd(prefix[i-1], A[i])

    suffix[N-1] = A[N-1]
    for i in range(N-2, -1, -1):
        suffix[i] = math.gcd(suffix[i+1], A[i])

    max_gcd = 0
    for i in range(N):
        if i == 0:
            current = suffix[1]
        elif i == N-1:
            current = prefix[N-2]
        else:
            current = math.gcd(prefix[i-1], suffix[i+1])
        if current > max_gcd:
            max_gcd = current
